import { execute as frameBufferManagerGetAttachmentObjectUseCase } from "../FrameBufferManager/usecase/FrameBufferManagerGetAttachmentObjectUseCase";
/**
 * @type {IAttachmentObject | null}
 * @private
 */
let $gradientAttachmentObject = null;
/**
 * @return {IAttachmentObject}
 * @method
 * @protected
 */
export const $getGradientAttachmentObject = () => {
    if (!$gradientAttachmentObject) {
        $gradientAttachmentObject = frameBufferManagerGetAttachmentObjectUseCase(512, 1, false);
    }
    return $gradientAttachmentObject;
};
/**
 * @type {number}
 * @private
 */
let $maxLength = 0;
/**
 * @description 最大長を返却
 *              Returns the maximum length
 *
 * @return {number}
 * @method
 * @protected
 */
export const $getGradientLUTGeneratorMaxLength = () => {
    return $maxLength;
};
/**
 * @description 最大長を設定
 *              Set the maximum length
 *
 * @param  {WebGL2RenderingContext} gl
 * @return {void}
 * @method
 * @protected
 */
export const $setGradientLUTGeneratorMaxLength = (gl) => {
    $maxLength = Math.floor(gl.getParameter(gl.MAX_FRAGMENT_UNIFORM_VECTORS) * 0.75);
};
/**
 * @type {Float32Array}
 * @private
 */
export const $rgbToLinearTable = new Float32Array(256);
/**
 * @type {Float32Array}
 * @private
 */
export const $rgbIdentityTable = new Float32Array(256);
for (let idx = 0; idx < 256; ++idx) {
    const t = idx / 255;
    $rgbToLinearTable[idx] = Math.pow(t, 2.23333333);
    $rgbIdentityTable[idx] = t;
}
